#!/usr/bin/env python3
"""A small JSON Schema command line validator.

This is an original reimplementation built from observed command-line behavior.
It intentionally has no third-party dependencies.
"""
from __future__ import annotations

import json
import math
import os
import re
import sys
import ssl
import urllib.parse
import urllib.request
import ipaddress
import uuid as uuidlib
from dataclasses import dataclass, field
from decimal import Decimal, InvalidOperation, getcontext
from datetime import datetime, date, time
from typing import Any, Dict, List, Optional, Tuple, Set, Union

getcontext().prec = 80

VERSION = "0.41.0"
VALID_DRAFTS = {"4", "6", "7", "2019", "2020"}
OUTPUTS = {"text", "flag", "list", "hierarchical"}
TYPE_NAMES = {"array", "boolean", "integer", "null", "number", "object", "string"}

HELP = """Usage: executable [OPTIONS] [SCHEMA]

Arguments:
  [SCHEMA]  The JSON Schema to validate with (i.e. schema.json)

Options:
  -i, --instance <INSTANCES>       A path to a JSON instance (i.e. filename.json) to validate (may be specified multiple times)
  -d, --draft <DRAFT>              Enforce a specific JSON Schema draft [possible values: 4, 6, 7, 2019, 2020]
      --assert-format              Turn ON format validation
      --no-assert-format           Turn OFF format validation
      --output <OUTPUT>            Select output style: text (default), flag, list, hierarchical [default: text] [possible values: text, flag, list, hierarchical]
  -v, --version                    Show program's version number and exit
      --errors-only                Only show validation errors
      --connect-timeout <SECONDS>  Timeout for establishing connections (in seconds)
      --timeout <SECONDS>          Total timeout for HTTP requests (in seconds)
  -k, --insecure                   Skip TLS certificate verification (dangerous!)
      --cacert <FILE>              Path to a custom CA certificate file (PEM format)
  -h, --help                       Print help"""


class CliExit(Exception):
    def __init__(self, code: int):
        self.code = code


class RuntimeCliError(Exception):
    pass


class SchemaInvalid(Exception):
    def __init__(self, message: str):
        self.message = message
        super().__init__(message)


@dataclass(frozen=True)
class JNum:
    raw: str
    dec: Decimal

    def __init__(self, raw: str):
        object.__setattr__(self, "raw", raw)
        object.__setattr__(self, "dec", Decimal(raw))

    def is_integer(self) -> bool:
        try:
            return self.dec == self.dec.to_integral_value()
        except InvalidOperation:
            return False

    def __lt__(self, other: "JNum") -> bool:
        return self.dec < other.dec

    def __le__(self, other: "JNum") -> bool:
        return self.dec <= other.dec

    def __gt__(self, other: "JNum") -> bool:
        return self.dec > other.dec

    def __ge__(self, other: "JNum") -> bool:
        return self.dec >= other.dec

    def __eq__(self, other: object) -> bool:
        if isinstance(other, JNum):
            return self.dec == other.dec
        return False

    def __hash__(self) -> int:
        return hash(("num", self.dec.normalize()))


def make_num(s: str) -> JNum:
    return JNum(s)


def object_pairs(pairs: List[Tuple[str, Any]]) -> Dict[str, Any]:
    d: Dict[str, Any] = {}
    for k, v in pairs:
        d[k] = v
    return d


def parse_constant(c: str):
    # Cause json.loads to fail; message is translated by parse_json_text.
    raise ValueError(c)


def line_col_from_pos(s: str, pos: int) -> Tuple[int, int]:
    # 1-based line, 1-based-ish column as used by serde for many errors.
    line = s.count("\n", 0, pos) + 1
    last_nl = s.rfind("\n", 0, pos)
    if last_nl < 0:
        col0 = pos
    else:
        col0 = pos - last_nl - 1
    return line, col0


def eof_line_col(s: str) -> Tuple[int, int]:
    if not s:
        return 1, 0
    if s.endswith("\n"):
        return s.count("\n") + 1, 0
    line = s.count("\n") + 1
    last_nl = s.rfind("\n")
    col = len(s) if last_nl < 0 else len(s) - last_nl - 1
    return line, col


def translate_json_error(text: str, err: Exception) -> str:
    if isinstance(err, ValueError) and not isinstance(err, json.JSONDecodeError):
        # NaN/Infinity and similar constants.
        bad = str(err)
        if bad.startswith("-"):
            return "invalid number at line 1 column 2"
        return "expected value at line 1 column 1"
    if not isinstance(err, json.JSONDecodeError):
        return str(err)

    msg = err.msg
    pos = err.pos
    lineno = err.lineno
    colno = err.colno
    stripped = text.strip()

    # Extra non-whitespace after a valid JSON value.
    if msg == "Extra data":
        return f"trailing characters at line {lineno} column {colno}"

    # A very common serde_json diagnostic for trailing comma before ] or }.
    prev_non_ws = None
    j = pos - 1
    while j >= 0:
        if not text[j].isspace():
            prev_non_ws = text[j]
            break
        j -= 1
    cur = text[pos] if pos < len(text) else ""
    if prev_non_ws == "," and cur in "]}":
        return f"trailing comma at line {lineno} column {colno}"

    # EOF cases.
    if pos >= len(text):
        line, col = eof_line_col(text)
        if msg.startswith("Unterminated string"):
            return f"EOF while parsing a string at line {line} column {col}"
        if msg.startswith("Expecting property name"):
            return f"EOF while parsing an object at line {line} column {col}"
        return f"EOF while parsing a value at line {line} column {col}"

    if msg.startswith("Unterminated string"):
        line, col = eof_line_col(text)
        return f"EOF while parsing a string at line {line} column {col}"

    # Incomplete literals/numbers often report at the beginning in Python.
    if msg == "Expecting value" and stripped in ("t", "tr", "tru", "f", "fa", "fal", "fals", "n", "nu", "nul"):
        line, col = eof_line_col(text)
        return f"EOF while parsing a value at line {line} column {col}"
    if msg == "Expecting value" and stripped in ("-",):
        line, col = eof_line_col(text)
        return f"EOF while parsing a value at line {line} column {col}"
    if msg == "Expecting value" and re.fullmatch(r"-?\d+(?:\.|[eE][+-]?)", stripped or ""):
        line, col = eof_line_col(text)
        return f"EOF while parsing a value at line {line} column {col}"

    # Invalid number forms such as 01 are reported by serde at the later digit.
    if msg == "Extra data" or (msg == "Expecting ',' delimiter" and pos < len(text)):
        return f"invalid number at line {lineno} column {colno}"
    if re.match(r"^-?0\d", stripped or ""):
        return f"invalid number at line 1 column {len(stripped)}"
    if stripped.startswith("-") and not stripped.startswith("-0") and len(stripped) > 1 and stripped[1].isalpha():
        return "invalid number at line 1 column 2"

    if msg == "Expecting value":
        # serde's column for this class is generally Python's 1-based colno.
        return f"expected value at line {lineno} column {colno}"

    if msg.startswith("Expecting property name"):
        return f"expected object key at line {lineno} column {max(colno - 1, 0)}"

    return f"{msg} at line {lineno} column {colno}"


def parse_json_text(text: str) -> Any:
    try:
        return json.loads(
            text,
            parse_int=make_num,
            parse_float=make_num,
            parse_constant=parse_constant,
            object_pairs_hook=object_pairs,
        )
    except Exception as e:
        raise RuntimeCliError(translate_json_error(text, e))


def os_error_message(e: OSError) -> str:
    # Observed output suppresses the filename.
    if isinstance(e, FileNotFoundError):
        return "No such file or directory (os error 2)"
    if isinstance(e, PermissionError):
        return "Permission denied (os error 13)"
    eno = getattr(e, "errno", None)
    if eno is not None:
        return f"{e.strerror} (os error {eno})"
    return str(e)


def read_path_text(path: str) -> str:
    try:
        with open(path, "r", encoding="utf-8") as f:
            return f.read()
    except OSError as e:
        raise RuntimeCliError(os_error_message(e))


def parse_json_file(path: str) -> Any:
    return parse_json_text(read_path_text(path))


def is_num(x: Any) -> bool:
    return isinstance(x, JNum)


def is_int_num(x: Any) -> bool:
    return isinstance(x, JNum) and x.is_integer()


def dec(x: Any) -> Decimal:
    assert isinstance(x, JNum)
    return x.dec


def json_quote(s: str) -> str:
    return json.dumps(s, ensure_ascii=False, separators=(",", ":"))


def render_json_value(v: Any) -> str:
    if isinstance(v, JNum):
        return v.raw
    if v is None:
        return "null"
    if v is True:
        return "true"
    if v is False:
        return "false"
    if isinstance(v, str):
        return json_quote(v)
    if isinstance(v, list):
        return "[" + ",".join(render_json_value(x) for x in v) + "]"
    if isinstance(v, dict):
        parts = []
        for k in sorted(v.keys()):
            parts.append(json_quote(str(k)) + ":" + render_json_value(v[k]))
        return "{" + ",".join(parts) + "}"
    # Should not normally happen, but keep JSON-looking output.
    return json.dumps(v, ensure_ascii=False, separators=(",", ":"), sort_keys=True)


def singular(n: Union[int, JNum], word: str) -> str:
    if isinstance(n, JNum):
        one = n.dec == 1
    else:
        one = n == 1
    return word if one else word + "s"


def join_values(vals: List[Any]) -> str:
    rendered = [render_json_value(v) for v in vals]
    if not rendered:
        return ""
    if len(rendered) == 1:
        return rendered[0]
    if len(rendered) == 2:
        return f"{rendered[0]} or {rendered[1]}"
    return ", ".join(rendered[:-1]) + " or " + rendered[-1]


def canonical(v: Any) -> Any:
    if isinstance(v, JNum):
        return ("num", str(v.dec.normalize()))
    if v is None:
        return ("null",)
    if v is True or v is False:
        return ("bool", bool(v))
    if isinstance(v, str):
        return ("str", v)
    if isinstance(v, list):
        return ("arr", tuple(canonical(x) for x in v))
    if isinstance(v, dict):
        return ("obj", tuple((k, canonical(v[k])) for k in sorted(v.keys())))
    return ("other", repr(v))


def json_equal(a: Any, b: Any) -> bool:
    return canonical(a) == canonical(b)


def type_of_instance(x: Any) -> str:
    if x is None:
        return "null"
    if isinstance(x, bool):
        return "boolean"
    if isinstance(x, str):
        return "string"
    if isinstance(x, list):
        return "array"
    if isinstance(x, dict):
        return "object"
    if isinstance(x, JNum):
        return "integer" if x.is_integer() else "number"
    return "unknown"


def type_matches(x: Any, t: str) -> bool:
    if t == "null":
        return x is None
    if t == "boolean":
        return isinstance(x, bool)
    if t == "string":
        return isinstance(x, str)
    if t == "array":
        return isinstance(x, list)
    if t == "object":
        return isinstance(x, dict)
    if t == "number":
        return isinstance(x, JNum)
    if t == "integer":
        return isinstance(x, JNum) and x.is_integer()
    return False


def allowed_types_from_schema(t: Any) -> Optional[List[str]]:
    if isinstance(t, str):
        return [t]
    if isinstance(t, list) and all(isinstance(x, str) for x in t):
        return sorted(set(t))
    return None


def type_error(instance: Any, allowed: List[str]) -> str:
    allowed = sorted(allowed)
    if len(allowed) == 1:
        return f"{render_json_value(instance)} is not of type {json_quote(allowed[0])}"
    return f"{render_json_value(instance)} is not of types " + ", ".join(json_quote(x) for x in allowed)


def pointer_escape(s: str) -> str:
    return s.replace("~", "~0").replace("/", "~1")


def join_ptr(base: str, token: str) -> str:
    if base == "":
        return "/" + pointer_escape(token)
    return base + "/" + pointer_escape(token)


def file_uri_for_path(path: str) -> str:
    abs_path = os.path.abspath(path)
    return urllib.parse.urljoin("file:", urllib.request.pathname2url(abs_path))


def schema_location(schema_uri: str, ptr: str) -> str:
    return schema_uri + "#" + ptr


@dataclass
class Node:
    evaluationPath: str
    instanceLocation: str
    schemaLocation: str
    valid: bool = True
    errors: Optional[Dict[str, Any]] = None
    annotations: Any = None
    droppedAnnotations: Any = None
    details: List["Node"] = field(default_factory=list)

    def to_obj(self, hierarchical: bool = False) -> Dict[str, Any]:
        obj: Dict[str, Any] = {}
        if self.annotations is not None:
            obj["annotations"] = self.annotations
        if hierarchical and self.details:
            obj["details"] = [d.to_obj(True) for d in self.details]
        if self.droppedAnnotations is not None:
            obj["droppedAnnotations"] = self.droppedAnnotations
        if self.errors is not None:
            obj["errors"] = self.errors
        obj["evaluationPath"] = self.evaluationPath
        obj["instanceLocation"] = self.instanceLocation
        obj["schemaLocation"] = self.schemaLocation
        obj["valid"] = self.valid
        return obj

    def flatten(self) -> List["Node"]:
        out = [self]
        for d in self.details:
            out.extend(d.flatten())
        return out


@dataclass
class ValidationResult:
    valid: bool
    errors: List[str]
    node: Optional[Node]
    evaluated_props: Set[str] = field(default_factory=set)
    evaluated_items: Set[int] = field(default_factory=set)


@dataclass
class Options:
    schema: Optional[str] = None
    instances: List[str] = field(default_factory=list)
    draft: Optional[str] = None
    assert_format: bool = False
    output: str = "text"
    errors_only: bool = False
    connect_timeout: Optional[float] = None
    timeout: Optional[float] = None
    insecure: bool = False
    cacert: Optional[str] = None
    version: bool = False


class SchemaLoader:
    def __init__(self, root_schema: Any, root_path: str, opts: Options):
        self.opts = opts
        self.root_path = root_path
        self.root_uri = file_uri_for_path(root_path)
        self.cache_by_uri: Dict[str, Any] = {self.root_uri: root_schema}
        self.cache_by_path: Dict[str, Any] = {os.path.abspath(root_path): root_schema}

    def load_uri(self, uri: str) -> Any:
        parsed = urllib.parse.urlparse(uri)
        nofrag = urllib.parse.urlunparse(parsed._replace(fragment=""))
        if parsed.scheme in ("http", "https"):
            if nofrag in self.cache_by_uri:
                return self.cache_by_uri[nofrag]
            try:
                ctx = None
                if parsed.scheme == "https":
                    if self.opts.insecure:
                        ctx = ssl._create_unverified_context()
                    elif self.opts.cacert:
                        ctx = ssl.create_default_context(cafile=self.opts.cacert)
                timeout = self.opts.timeout if self.opts.timeout is not None else self.opts.connect_timeout
                with urllib.request.urlopen(nofrag, timeout=timeout, context=ctx) as r:
                    text = r.read().decode("utf-8")
                doc = parse_json_text(text)
                self.cache_by_uri[nofrag] = doc
                return doc
            except RuntimeCliError:
                raise
            except Exception as e:
                raise RuntimeCliError(str(e))
        if parsed.scheme == "file":
            path = urllib.request.url2pathname(parsed.path)
        elif parsed.scheme == "":
            path = uri
        else:
            # The observed top-level CLI treats URLs as paths; for references, report a normal error.
            raise RuntimeCliError("No such file or directory (os error 2)")
        path_abs = os.path.abspath(path)
        if path_abs in self.cache_by_path:
            return self.cache_by_path[path_abs]
        doc = parse_json_file(path_abs)
        self.cache_by_path[path_abs] = doc
        self.cache_by_uri[file_uri_for_path(path_abs)] = doc
        return doc

    def resolve_pointer(self, doc: Any, pointer: str) -> Any:
        if pointer in ("", None):
            return doc
        if not pointer.startswith("/"):
            raise SchemaInvalid(f"Pointer '{pointer}' does not exist")
        cur = doc
        for raw in pointer.split("/")[1:]:
            tok = raw.replace("~1", "/").replace("~0", "~")
            if isinstance(cur, dict) and tok in cur:
                cur = cur[tok]
            elif isinstance(cur, list):
                try:
                    idx = int(tok)
                    cur = cur[idx]
                except Exception:
                    raise SchemaInvalid(f"Pointer '{pointer}' does not exist")
            else:
                raise SchemaInvalid(f"Pointer '{pointer}' does not exist")
        return cur

    def resolve_ref(self, ref: str, base_uri: str) -> Tuple[Any, str, str]:
        # returns (schema, document_uri_without_fragment, pointer)
        full = urllib.parse.urljoin(base_uri + ("" if base_uri.endswith("/") else ""), ref)
        parsed = urllib.parse.urlparse(full)
        frag = parsed.fragment
        nofrag = urllib.parse.urlunparse(parsed._replace(fragment=""))
        if nofrag == "":
            nofrag = self.root_uri
        doc = self.load_uri(nofrag)
        pointer = urllib.parse.unquote(frag)
        schema = self.resolve_pointer(doc, pointer)
        return schema, nofrag, pointer


def detect_draft(schema: Any, fallback: str = "2020") -> str:
    if isinstance(schema, dict):
        s = schema.get("$schema")
        if isinstance(s, str):
            low = s.lower()
            if "draft-04" in low or "draft/04" in low:
                return "4"
            if "draft-06" in low or "draft/06" in low:
                return "6"
            if "draft-07" in low or "draft/07" in low:
                return "7"
            if "2019-09" in low or "draft/2019" in low:
                return "2019"
            if "2020-12" in low or "draft/2020" in low:
                return "2020"
    return fallback


def draft_num(d: str) -> int:
    return {"4": 4, "6": 6, "7": 7, "2019": 2019, "2020": 2020}[d]


def is_schema_obj(x: Any) -> bool:
    return isinstance(x, (dict, bool))


def meta_type_error(v: Any, types: List[str]) -> str:
    return type_error(v, types)


def check_regex(pattern: str) -> bool:
    try:
        re.compile(pattern)
        return True
    except re.error:
        return False


def validate_schema_meta(schema: Any, draft: str, loader: Optional[SchemaLoader] = None, base_uri: Optional[str] = None, root: bool = True) -> None:
    """A pragmatic meta-schema validator for the keywords implemented below."""
    if isinstance(schema, bool):
        return
    if not isinstance(schema, dict):
        raise SchemaInvalid(meta_type_error(schema, ["boolean", "object"]))

    # Validate references exist early, matching observed missing-pointer behavior.
    if "$ref" in schema:
        if not isinstance(schema["$ref"], str):
            raise SchemaInvalid(meta_type_error(schema["$ref"], ["string"]))
        if loader is not None:
            try:
                ref_schema, ref_uri, _ = loader.resolve_ref(schema["$ref"], base_uri or loader.root_uri)
                # Avoid endless loops; just existence check is enough here.
            except SchemaInvalid:
                raise
            except RuntimeCliError:
                raise

    if "type" in schema:
        t = schema["type"]
        ok = False
        if isinstance(t, str):
            ok = t in TYPE_NAMES
        elif isinstance(t, list):
            ok = bool(t) and all(isinstance(x, str) and x in TYPE_NAMES for x in t) and len(set(t)) == len(t)
        if not ok:
            raise SchemaInvalid(f"{render_json_value(t)} is not valid under any of the schemas listed in the 'anyOf' keyword")

    if "enum" in schema and not isinstance(schema["enum"], list):
        raise SchemaInvalid(meta_type_error(schema["enum"], ["array"]))

    if "minimum" in schema and not is_num(schema["minimum"]):
        raise SchemaInvalid(meta_type_error(schema["minimum"], ["number"]))
    if "maximum" in schema and not is_num(schema["maximum"]):
        raise SchemaInvalid(meta_type_error(schema["maximum"], ["number"]))

    if "exclusiveMinimum" in schema:
        v = schema["exclusiveMinimum"]
        if draft == "4":
            if not isinstance(v, bool):
                raise SchemaInvalid(meta_type_error(v, ["boolean"]))
        else:
            if not is_num(v):
                raise SchemaInvalid(meta_type_error(v, ["number"]))
    if "exclusiveMaximum" in schema:
        v = schema["exclusiveMaximum"]
        if draft == "4":
            if not isinstance(v, bool):
                raise SchemaInvalid(meta_type_error(v, ["boolean"]))
        else:
            if not is_num(v):
                raise SchemaInvalid(meta_type_error(v, ["number"]))

    if "multipleOf" in schema:
        v = schema["multipleOf"]
        if not is_num(v):
            raise SchemaInvalid(meta_type_error(v, ["number"]))
        if v.dec <= 0:
            raise SchemaInvalid(f"{render_json_value(v)} is less than or equal to the minimum of 0")

    for kw in ("minLength", "maxLength", "minItems", "maxItems", "minProperties", "maxProperties", "minContains", "maxContains"):
        if kw in schema:
            v = schema[kw]
            if not is_int_num(v):
                raise SchemaInvalid(meta_type_error(v, ["integer"]))
            if v.dec < 0:
                raise SchemaInvalid(f"{render_json_value(v)} is less than the minimum of 0")

    if "pattern" in schema:
        v = schema["pattern"]
        if not isinstance(v, str):
            raise SchemaInvalid(meta_type_error(v, ["string"]))
        if not check_regex(v):
            raise SchemaInvalid(f"{render_json_value(v)} is not a {json_quote('regex')}")

    if "format" in schema and not isinstance(schema["format"], str):
        raise SchemaInvalid(meta_type_error(schema["format"], ["string"]))

    if "uniqueItems" in schema and not isinstance(schema["uniqueItems"], bool):
        raise SchemaInvalid(meta_type_error(schema["uniqueItems"], ["boolean"]))

    def check_sub(s: Any):
        if not is_schema_obj(s):
            raise SchemaInvalid(meta_type_error(s, ["boolean", "object"]))
        validate_schema_meta(s, draft, loader, base_uri, root=False)

    # Applicator schema-valued keywords.
    if "items" in schema:
        v = schema["items"]
        if draft == "2020":
            if not is_schema_obj(v):
                raise SchemaInvalid(meta_type_error(v, ["boolean", "object"]))
            check_sub(v)
        else:
            if isinstance(v, list):
                for it in v:
                    if not is_schema_obj(it):
                        raise SchemaInvalid(meta_type_error(it, ["boolean", "object"]))
                    validate_schema_meta(it, draft, loader, base_uri, root=False)
            elif is_schema_obj(v):
                check_sub(v)
            else:
                raise SchemaInvalid(meta_type_error(v, ["array", "boolean", "object"]))

    if draft == "2020" and "prefixItems" in schema:
        v = schema["prefixItems"]
        if not isinstance(v, list):
            raise SchemaInvalid(meta_type_error(v, ["array"]))
        for it in v:
            if not is_schema_obj(it):
                raise SchemaInvalid(meta_type_error(it, ["boolean", "object"]))
            validate_schema_meta(it, draft, loader, base_uri, root=False)

    for kw in ("additionalItems", "contains", "additionalProperties", "propertyNames", "unevaluatedProperties", "unevaluatedItems", "if", "then", "else", "not"):
        if kw in schema:
            # Only check keywords known in the effective draft or legacy schema-valued ones.
            if kw == "contains" and draft_num(draft) < 6:
                continue
            if kw == "propertyNames" and draft_num(draft) < 6:
                continue
            if kw in ("unevaluatedProperties", "unevaluatedItems") and draft_num(draft) < 2019:
                continue
            if kw in ("if", "then", "else") and draft_num(draft) < 7:
                continue
            v = schema[kw]
            if not is_schema_obj(v):
                raise SchemaInvalid(meta_type_error(v, ["boolean", "object"]))
            validate_schema_meta(v, draft, loader, base_uri, root=False)

    for kw in ("allOf", "anyOf", "oneOf"):
        if kw in schema:
            v = schema[kw]
            if not isinstance(v, list):
                raise SchemaInvalid(meta_type_error(v, ["array"]))
            for it in v:
                if not is_schema_obj(it):
                    raise SchemaInvalid(meta_type_error(it, ["boolean", "object"]))
                validate_schema_meta(it, draft, loader, base_uri, root=False)

    if "properties" in schema:
        v = schema["properties"]
        if not isinstance(v, dict):
            raise SchemaInvalid(meta_type_error(v, ["object"]))
        for k in sorted(v.keys()):
            if not is_schema_obj(v[k]):
                raise SchemaInvalid(meta_type_error(v[k], ["boolean", "object"]))
            validate_schema_meta(v[k], draft, loader, base_uri, root=False)

    if "patternProperties" in schema:
        v = schema["patternProperties"]
        if not isinstance(v, dict):
            raise SchemaInvalid(meta_type_error(v, ["object"]))
        for k in sorted(v.keys()):
            if not check_regex(k):
                # Observed meta output is a little odd for propertyNames; this is close for common cases.
                raise SchemaInvalid(f"{render_json_value(v[k])} is not a {json_quote('regex')}")
            if not is_schema_obj(v[k]):
                raise SchemaInvalid(meta_type_error(v[k], ["boolean", "object"]))
            validate_schema_meta(v[k], draft, loader, base_uri, root=False)

    if "required" in schema:
        v = schema["required"]
        if not isinstance(v, list):
            raise SchemaInvalid(meta_type_error(v, ["array"]))
        seen = set()
        for it in v:
            if not isinstance(it, str):
                raise SchemaInvalid(meta_type_error(it, ["string"]))
            if it in seen:
                raise SchemaInvalid(f"{render_json_value(v)} has non-unique elements")
            seen.add(it)

    if "dependentRequired" in schema:
        v = schema["dependentRequired"]
        if not isinstance(v, dict):
            raise SchemaInvalid(meta_type_error(v, ["object"]))
        for dep, arr in sorted(v.items()):
            if not isinstance(arr, list):
                raise SchemaInvalid(meta_type_error(arr, ["array"]))
            seen = set()
            for it in arr:
                if not isinstance(it, str):
                    raise SchemaInvalid(meta_type_error(it, ["string"]))
                if it in seen:
                    raise SchemaInvalid(f"{render_json_value(arr)} has non-unique elements")
                seen.add(it)

    if "dependentSchemas" in schema:
        v = schema["dependentSchemas"]
        if not isinstance(v, dict):
            raise SchemaInvalid(meta_type_error(v, ["object"]))
        for k in sorted(v.keys()):
            if not is_schema_obj(v[k]):
                raise SchemaInvalid(meta_type_error(v[k], ["boolean", "object"]))
            validate_schema_meta(v[k], draft, loader, base_uri, root=False)

    if "dependencies" in schema:
        v = schema["dependencies"]
        if not isinstance(v, dict):
            raise SchemaInvalid(meta_type_error(v, ["object"]))
        for k in sorted(v.keys()):
            dep = v[k]
            if isinstance(dep, list):
                seen = set()
                for it in dep:
                    if not isinstance(it, str):
                        raise SchemaInvalid(meta_type_error(it, ["string"]))
                    if it in seen:
                        raise SchemaInvalid(f"{render_json_value(dep)} has non-unique elements")
                    seen.add(it)
            elif is_schema_obj(dep):
                validate_schema_meta(dep, draft, loader, base_uri, root=False)
            else:
                raise SchemaInvalid(f"{render_json_value(dep)} is not valid under any of the schemas listed in the 'anyOf' keyword")

    for defs_kw in ("$defs", "definitions"):
        if defs_kw in schema and isinstance(schema[defs_kw], dict):
            for k in sorted(schema[defs_kw].keys()):
                if is_schema_obj(schema[defs_kw][k]):
                    validate_schema_meta(schema[defs_kw][k], draft, loader, base_uri, root=False)


def format_valid(fmt: str, s: str) -> bool:
    try:
        if fmt == "email":
            return bool(re.match(r"^[^@\s]+@[^@\s]+\.[^@\s]+$", s))
        if fmt == "ipv4":
            ipaddress.IPv4Address(s); return True
        if fmt == "ipv6":
            ipaddress.IPv6Address(s); return True
        if fmt == "uuid":
            uuidlib.UUID(s); return bool(re.match(r"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$", s))
        if fmt == "date":
            date.fromisoformat(s); return bool(re.match(r"^\d{4}-\d{2}-\d{2}$", s))
        if fmt == "time":
            # Accept RFC3339-ish times; Python handles HH:MM:SS[.frac][+HH:MM].
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            time.fromisoformat(ss); return True
        if fmt == "date-time":
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            datetime.fromisoformat(ss); return "T" in s or "t" in s
        if fmt == "uri":
            p = urllib.parse.urlparse(s)
            return bool(p.scheme) and " " not in s
        if fmt == "uri-reference":
            return " " not in s
        if fmt == "hostname":
            if len(s) > 253 or not s:
                return False
            labels = s.rstrip('.').split('.')
            return all(0 < len(l) <= 63 and re.match(r"^[A-Za-z0-9-]+$", l) and not l.startswith('-') and not l.endswith('-') for l in labels)
        if fmt == "regex":
            return check_regex(s)
        if fmt in ("iri", "iri-reference"):
            return " " not in s
        if fmt == "json-pointer":
            return s == "" or s.startswith("/")
        if fmt == "relative-json-pointer":
            return bool(re.match(r"^(0|[1-9][0-9]*)(#|(/.*)?)$", s))
    except Exception:
        return False
    return True  # Unknown formats are annotations only.


class Validator:
    def __init__(self, loader: SchemaLoader, draft: str, assert_format: bool):
        self.loader = loader
        self.draft = draft
        self.assert_format = assert_format

    def validate(self, schema: Any, instance: Any, eval_path: str = "", inst_path: str = "", schema_uri: Optional[str] = None, schema_ptr: str = "", collect: bool = False, base_uri: Optional[str] = None) -> ValidationResult:
        if schema_uri is None:
            schema_uri = self.loader.root_uri
        if base_uri is None:
            base_uri = schema_uri
        node = Node(eval_path, inst_path, schema_location(schema_uri, schema_ptr), True) if collect else None
        errors: List[str] = []
        eval_props: Set[str] = set()
        eval_items: Set[int] = set()

        def add_err(keyword: str, msg: str, child_path: Optional[str] = None, child_schema_ptr: Optional[str] = None, child_inst_path: Optional[str] = None):
            errors.append(msg)
            if collect:
                ep = child_path if child_path is not None else join_ptr(eval_path, keyword)
                sp = child_schema_ptr if child_schema_ptr is not None else join_ptr(schema_ptr, keyword)
                ip = inst_path if child_inst_path is None else child_inst_path
                n = Node(ep, ip, schema_location(schema_uri, sp), False, errors={keyword: msg})
                node.details.append(n)  # type: ignore

        def add_child(res: ValidationResult):
            nonlocal errors, eval_props, eval_items
            errors.extend(res.errors)
            eval_props.update(res.evaluated_props)
            eval_items.update(res.evaluated_items)
            if collect and res.node is not None:
                node.details.append(res.node)  # type: ignore

        # Boolean schemas.
        if schema is True:
            if collect:
                node.valid = True  # type: ignore
            return ValidationResult(True, [], node, eval_props, eval_items)
        if schema is False:
            msg = f"False schema does not allow {render_json_value(instance)}"
            if collect:
                node.valid = False  # type: ignore
                node.errors = {"falseSchema": msg}  # type: ignore
            return ValidationResult(False, [msg], node, eval_props, eval_items)
        if not isinstance(schema, dict):
            # Should be caught by meta-validation; treat as no-op to avoid crashes.
            return ValidationResult(True, [], node, eval_props, eval_items)

        # $id changes base URI for relative references in descendants.
        cur_base_uri = base_uri
        if isinstance(schema.get("$id"), str):
            cur_base_uri = urllib.parse.urljoin(base_uri, schema["$id"])

        # $ref is first. Drafts <= 7 ignore siblings.
        if "$ref" in schema and isinstance(schema["$ref"], str):
            ref_schema, ref_doc_uri, ref_ptr = self.loader.resolve_ref(schema["$ref"], cur_base_uri)
            ref_eval = join_ptr(eval_path, "$ref")
            ref_res = self.validate(ref_schema, instance, ref_eval, inst_path, ref_doc_uri, ref_ptr, collect, ref_doc_uri)
            if collect:
                # Wrap referenced evaluation in a $ref node to match common output shape.
                ref_node = Node(ref_eval, inst_path, schema_location(schema_uri, ref_ptr), ref_res.valid)
                if ref_res.node is not None:
                    ref_node.details = ref_res.node.details
                    if ref_res.node.errors:
                        ref_node.errors = ref_res.node.errors
                node.details.append(ref_node)  # type: ignore
            errors.extend(ref_res.errors)
            eval_props.update(ref_res.evaluated_props)
            eval_items.update(ref_res.evaluated_items)
            if draft_num(self.draft) <= 7:
                if collect:
                    node.valid = not errors  # type: ignore
                return ValidationResult(not errors, errors, node, eval_props, eval_items)

        # Validation keyword order observed from text output.
        if "type" in schema:
            allowed = allowed_types_from_schema(schema["type"])
            if allowed and not any(type_matches(instance, t) for t in allowed):
                add_err("type", type_error(instance, allowed))
            elif collect:
                n = Node(join_ptr(eval_path, "type"), inst_path, schema_location(schema_uri, join_ptr(schema_ptr, "type")), True)
                node.details.append(n)  # type: ignore

        if draft_num(self.draft) >= 6 and "const" in schema:
            if not json_equal(instance, schema["const"]):
                add_err("const", f"{render_json_value(schema['const'])} was expected")
            elif collect:
                node.details.append(Node(join_ptr(eval_path, "const"), inst_path, schema_location(schema_uri, join_ptr(schema_ptr, "const")), True))  # type: ignore

        if "enum" in schema and isinstance(schema["enum"], list):
            if not any(json_equal(instance, v) for v in schema["enum"]):
                add_err("enum", f"{render_json_value(instance)} is not one of {join_values(schema['enum'])}")
            elif collect:
                node.details.append(Node(join_ptr(eval_path, "enum"), inst_path, schema_location(schema_uri, join_ptr(schema_ptr, "enum")), True))  # type: ignore

        # Numeric keywords apply only to numbers.
        if is_num(instance):
            if self.draft == "4":
                ex_min = schema.get("exclusiveMinimum") is True
                ex_max = schema.get("exclusiveMaximum") is True
                if "minimum" in schema and is_num(schema["minimum"]):
                    if ex_min:
                        if instance.dec <= schema["minimum"].dec:
                            add_err("exclusiveMinimum", f"{render_json_value(instance)} is less than or equal to the minimum of {render_json_value(schema['minimum'])}", child_schema_ptr=join_ptr(schema_ptr, "exclusiveMinimum"))
                    else:
                        if instance.dec < schema["minimum"].dec:
                            add_err("minimum", f"{render_json_value(instance)} is less than the minimum of {render_json_value(schema['minimum'])}")
                if "maximum" in schema and is_num(schema["maximum"]):
                    if ex_max:
                        if instance.dec >= schema["maximum"].dec:
                            add_err("exclusiveMaximum", f"{render_json_value(instance)} is greater than or equal to the maximum of {render_json_value(schema['maximum'])}", child_schema_ptr=join_ptr(schema_ptr, "exclusiveMaximum"))
                    else:
                        if instance.dec > schema["maximum"].dec:
                            add_err("maximum", f"{render_json_value(instance)} is greater than the maximum of {render_json_value(schema['maximum'])}")
            else:
                if "minimum" in schema and is_num(schema["minimum"]) and instance.dec < schema["minimum"].dec:
                    add_err("minimum", f"{render_json_value(instance)} is less than the minimum of {render_json_value(schema['minimum'])}")
                if "maximum" in schema and is_num(schema["maximum"]) and instance.dec > schema["maximum"].dec:
                    add_err("maximum", f"{render_json_value(instance)} is greater than the maximum of {render_json_value(schema['maximum'])}")
                if "exclusiveMinimum" in schema and is_num(schema["exclusiveMinimum"]) and instance.dec <= schema["exclusiveMinimum"].dec:
                    add_err("exclusiveMinimum", f"{render_json_value(instance)} is less than or equal to the minimum of {render_json_value(schema['exclusiveMinimum'])}")
                if "exclusiveMaximum" in schema and is_num(schema["exclusiveMaximum"]) and instance.dec >= schema["exclusiveMaximum"].dec:
                    add_err("exclusiveMaximum", f"{render_json_value(instance)} is greater than or equal to the maximum of {render_json_value(schema['exclusiveMaximum'])}")
            if "multipleOf" in schema and is_num(schema["multipleOf"]) and schema["multipleOf"].dec != 0:
                try:
                    q = instance.dec / schema["multipleOf"].dec
                    if q != q.to_integral_value():
                        add_err("multipleOf", f"{render_json_value(instance)} is not a multiple of {render_json_value(schema['multipleOf'])}")
                except Exception:
                    pass

        # Strings.
        if isinstance(instance, str):
            if "minLength" in schema and is_int_num(schema["minLength"]):
                n = int(schema["minLength"].dec)
                if len(instance) < n:
                    add_err("minLength", f"{render_json_value(instance)} is shorter than {render_json_value(schema['minLength'])} {singular(n, 'character')}")
            if "maxLength" in schema and is_int_num(schema["maxLength"]):
                n = int(schema["maxLength"].dec)
                if len(instance) > n:
                    add_err("maxLength", f"{render_json_value(instance)} is longer than {render_json_value(schema['maxLength'])} {singular(n, 'character')}")
            if "pattern" in schema and isinstance(schema["pattern"], str):
                try:
                    if re.search(schema["pattern"], instance) is None:
                        add_err("pattern", f"{render_json_value(instance)} does not match {render_json_value(schema['pattern'])}")
                except re.error:
                    pass
            if self.assert_format and "format" in schema and isinstance(schema["format"], str):
                fmt = schema["format"]
                if not format_valid(fmt, instance):
                    add_err("format", f"{render_json_value(instance)} is not a {render_json_value(fmt)}")

        # Objects.
        if isinstance(instance, dict):
            prop_names = set(instance.keys())
            if "minProperties" in schema and is_int_num(schema["minProperties"]):
                n = int(schema["minProperties"].dec)
                if len(instance) < n:
                    add_err("minProperties", f"{render_json_value(instance)} has less than {render_json_value(schema['minProperties'])} {singular(n, 'property')}")
            if "maxProperties" in schema and is_int_num(schema["maxProperties"]):
                n = int(schema["maxProperties"].dec)
                if len(instance) > n:
                    add_err("maxProperties", f"{render_json_value(instance)} has more than {render_json_value(schema['maxProperties'])} {singular(n, 'property')}")

            props_valid = True
            prop_ann: List[str] = []
            props_node: Optional[Node] = None
            if collect and isinstance(schema.get("properties"), dict):
                props_node = Node(join_ptr(eval_path, "properties"), inst_path, schema_location(schema_uri, join_ptr(schema_ptr, "properties")), True)

            if isinstance(schema.get("properties"), dict):
                for name in sorted(schema["properties"].keys()):
                    if name in instance:
                        prop_ann.append(name)
                        eval_props.add(name)
                        sub = schema["properties"][name]
                        res = self.validate(sub, instance[name], join_ptr(join_ptr(eval_path, "properties"), name), join_ptr(inst_path, name), schema_uri, join_ptr(join_ptr(schema_ptr, "properties"), name), collect, cur_base_uri)
                        if res.errors:
                            props_valid = False
                        errors.extend(res.errors)
                        eval_props.update(res.evaluated_props)
                        eval_items.update(res.evaluated_items)
                        if collect and props_node is not None and res.node is not None:
                            props_node.details.append(res.node)
            if collect and props_node is not None:
                props_node.valid = props_valid
                if prop_ann:
                    if props_valid:
                        props_node.annotations = prop_ann
                    else:
                        props_node.droppedAnnotations = prop_ann
                node.details.append(props_node)  # type: ignore

            # patternProperties
            matched_by_patterns: Set[str] = set()
            if isinstance(schema.get("patternProperties"), dict):
                for name in sorted(instance.keys()):
                    for pat in sorted(schema["patternProperties"].keys()):
                        try:
                            if re.search(pat, name):
                                matched_by_patterns.add(name)
                                eval_props.add(name)
                                sub = schema["patternProperties"][pat]
                                res = self.validate(sub, instance[name], join_ptr(join_ptr(eval_path, "patternProperties"), pat), join_ptr(inst_path, name), schema_uri, join_ptr(join_ptr(schema_ptr, "patternProperties"), pat), collect, cur_base_uri)
                                add_child(res)
                        except re.error:
                            pass

            # additionalProperties after properties / patternProperties.
            if "additionalProperties" in schema:
                addl_schema = schema["additionalProperties"]
                declared = set(schema.get("properties", {}).keys()) if isinstance(schema.get("properties"), dict) else set()
                additional = sorted(prop_names - declared - matched_by_patterns)
                if addl_schema is False:
                    if additional:
                        if declared or matched_by_patterns:
                            msg = unexpected_props_msg("Additional properties are not allowed", additional)
                            add_err("additionalProperties", msg)
                        else:
                            # Observed behavior validates the first property against false schema.
                            first = additional[0]
                            msg = f"False schema does not allow {render_json_value(instance[first])}"
                            add_err("falseSchema", msg, child_path=join_ptr(eval_path, "additionalProperties"), child_schema_ptr=join_ptr(schema_ptr, "additionalProperties"), child_inst_path=join_ptr(inst_path, first))
                elif is_schema_obj(addl_schema):
                    for name in additional:
                        eval_props.add(name)
                        res = self.validate(addl_schema, instance[name], join_ptr(eval_path, "additionalProperties"), join_ptr(inst_path, name), schema_uri, join_ptr(schema_ptr, "additionalProperties"), collect, cur_base_uri)
                        add_child(res)

            if draft_num(self.draft) >= 6 and is_schema_obj(schema.get("propertyNames")):
                for name in sorted(instance.keys()):
                    res = self.validate(schema["propertyNames"], name, join_ptr(eval_path, "propertyNames"), join_ptr(inst_path, name), schema_uri, join_ptr(schema_ptr, "propertyNames"), collect, cur_base_uri)
                    add_child(res)

            if isinstance(schema.get("required"), list):
                for req in schema["required"]:
                    if isinstance(req, str) and req not in instance:
                        add_err("required", f"{render_json_value(req)} is a required property")
                    elif collect and isinstance(req, str):
                        pass
                if collect and "required" in schema:
                    # Original includes a valid required node when all requirements pass.
                    missing = [r for r in schema["required"] if isinstance(r, str) and r not in instance]
                    if not missing:
                        node.details.append(Node(join_ptr(eval_path, "required"), inst_path, schema_location(schema_uri, join_ptr(schema_ptr, "required")), True))  # type: ignore

            if isinstance(schema.get("dependencies"), dict):
                for name in sorted(schema["dependencies"].keys()):
                    if name in instance:
                        dep = schema["dependencies"][name]
                        if isinstance(dep, list):
                            for req in dep:
                                if isinstance(req, str) and req not in instance:
                                    add_err("dependencies", f"{render_json_value(req)} is a required property")
                        elif is_schema_obj(dep):
                            res = self.validate(dep, instance, join_ptr(join_ptr(eval_path, "dependencies"), name), inst_path, schema_uri, join_ptr(join_ptr(schema_ptr, "dependencies"), name), collect, cur_base_uri)
                            add_child(res)

            if draft_num(self.draft) >= 2019 and isinstance(schema.get("dependentRequired"), dict):
                for name in sorted(schema["dependentRequired"].keys()):
                    if name in instance and isinstance(schema["dependentRequired"][name], list):
                        for req in schema["dependentRequired"][name]:
                            if isinstance(req, str) and req not in instance:
                                add_err("dependentRequired", f"{render_json_value(req)} is a required property")

            if draft_num(self.draft) >= 2019 and isinstance(schema.get("dependentSchemas"), dict):
                for name in sorted(schema["dependentSchemas"].keys()):
                    if name in instance and is_schema_obj(schema["dependentSchemas"][name]):
                        res = self.validate(schema["dependentSchemas"][name], instance, join_ptr(join_ptr(eval_path, "dependentSchemas"), name), inst_path, schema_uri, join_ptr(join_ptr(schema_ptr, "dependentSchemas"), name), collect, cur_base_uri)
                        add_child(res)

            if draft_num(self.draft) >= 2019 and "unevaluatedProperties" in schema:
                uneval = sorted(prop_names - eval_props)
                us = schema["unevaluatedProperties"]
                if uneval:
                    # jsonschema-rs reports unexpected names for false or failing schema.
                    if us is False:
                        add_err("unevaluatedProperties", unexpected_props_msg("Unevaluated properties are not allowed", uneval))
                    elif is_schema_obj(us):
                        bad: List[str] = []
                        for name in uneval:
                            res = self.validate(us, instance[name], join_ptr(eval_path, "unevaluatedProperties"), join_ptr(inst_path, name), schema_uri, join_ptr(schema_ptr, "unevaluatedProperties"), False, cur_base_uri)
                            if not res.valid:
                                bad.append(name)
                        if bad:
                            add_err("unevaluatedProperties", unexpected_props_msg("Unevaluated properties are not allowed", bad))

        # Arrays.
        if isinstance(instance, list):
            if "minItems" in schema and is_int_num(schema["minItems"]):
                n = int(schema["minItems"].dec)
                if len(instance) < n:
                    add_err("minItems", f"{render_json_value(instance)} has less than {render_json_value(schema['minItems'])} {singular(n, 'item')}")
            if "maxItems" in schema and is_int_num(schema["maxItems"]):
                n = int(schema["maxItems"].dec)
                if len(instance) > n:
                    add_err("maxItems", f"{render_json_value(instance)} has more than {render_json_value(schema['maxItems'])} {singular(n, 'item')}")
            if schema.get("uniqueItems") is True:
                seen = set()
                dup = False
                for it in instance:
                    c = canonical(it)
                    if c in seen:
                        dup = True
                        break
                    seen.add(c)
                if dup:
                    add_err("uniqueItems", f"{render_json_value(instance)} has non-unique elements")

            if self.draft == "2020":
                prefix_len = 0
                if isinstance(schema.get("prefixItems"), list):
                    for idx, sub in enumerate(schema["prefixItems"]):
                        if idx < len(instance) and is_schema_obj(sub):
                            eval_items.add(idx)
                            res = self.validate(sub, instance[idx], join_ptr(join_ptr(eval_path, "prefixItems"), str(idx)), join_ptr(inst_path, str(idx)), schema_uri, join_ptr(join_ptr(schema_ptr, "prefixItems"), str(idx)), collect, cur_base_uri)
                            add_child(res)
                    prefix_len = len(schema["prefixItems"])
                if "items" in schema and is_schema_obj(schema["items"]):
                    for idx in range(prefix_len, len(instance)):
                        eval_items.add(idx)
                        res = self.validate(schema["items"], instance[idx], join_ptr(eval_path, "items"), join_ptr(inst_path, str(idx)), schema_uri, join_ptr(schema_ptr, "items"), collect, cur_base_uri)
                        add_child(res)
            else:
                if "items" in schema:
                    it = schema["items"]
                    if isinstance(it, list):
                        for idx, sub in enumerate(it):
                            if idx < len(instance) and is_schema_obj(sub):
                                eval_items.add(idx)
                                res = self.validate(sub, instance[idx], join_ptr(join_ptr(eval_path, "items"), str(idx)), join_ptr(inst_path, str(idx)), schema_uri, join_ptr(join_ptr(schema_ptr, "items"), str(idx)), collect, cur_base_uri)
                                add_child(res)
                        if len(instance) > len(it) and "additionalItems" in schema:
                            extra_idxs = list(range(len(it), len(instance)))
                            addl = schema["additionalItems"]
                            if addl is False:
                                vals = [render_json_value(instance[i]) for i in extra_idxs]
                                if len(vals) == 1:
                                    msg = f"Additional items are not allowed ({vals[0]} was unexpected)"
                                else:
                                    msg = f"Additional items are not allowed ({', '.join(vals)} were unexpected)"
                                add_err("additionalItems", msg)
                            elif is_schema_obj(addl):
                                for idx in extra_idxs:
                                    eval_items.add(idx)
                                    res = self.validate(addl, instance[idx], join_ptr(eval_path, "additionalItems"), join_ptr(inst_path, str(idx)), schema_uri, join_ptr(schema_ptr, "additionalItems"), collect, cur_base_uri)
                                    add_child(res)
                    elif is_schema_obj(it):
                        for idx, val in enumerate(instance):
                            eval_items.add(idx)
                            res = self.validate(it, val, join_ptr(eval_path, "items"), join_ptr(inst_path, str(idx)), schema_uri, join_ptr(schema_ptr, "items"), collect, cur_base_uri)
                            add_child(res)

            if draft_num(self.draft) >= 6 and "contains" in schema and is_schema_obj(schema["contains"]):
                good_idxs = []
                for idx, val in enumerate(instance):
                    res = self.validate(schema["contains"], val, join_ptr(eval_path, "contains"), join_ptr(inst_path, str(idx)), schema_uri, join_ptr(schema_ptr, "contains"), False, cur_base_uri)
                    if res.valid:
                        good_idxs.append(idx)
                minc = 1
                maxc = None
                if draft_num(self.draft) >= 2019:
                    if is_int_num(schema.get("minContains")):
                        minc = int(schema["minContains"].dec)
                    if is_int_num(schema.get("maxContains")):
                        maxc = int(schema["maxContains"].dec)
                ok = len(good_idxs) >= minc and (maxc is None or len(good_idxs) <= maxc)
                if not ok:
                    add_err("contains", f"None of {render_json_value(instance)} are valid under the given schema")
                elif collect:
                    n = Node(join_ptr(eval_path, "contains"), inst_path, schema_location(schema_uri, join_ptr(schema_ptr, "contains")), True)
                    n.annotations = good_idxs
                    node.details.append(n)  # type: ignore

            if draft_num(self.draft) >= 2019 and "unevaluatedItems" in schema:
                uneval = [i for i in range(len(instance)) if i not in eval_items]
                us = schema["unevaluatedItems"]
                if uneval:
                    badidx: List[int] = []
                    if us is False:
                        badidx = uneval
                    elif is_schema_obj(us):
                        for idx in uneval:
                            res = self.validate(us, instance[idx], join_ptr(eval_path, "unevaluatedItems"), join_ptr(inst_path, str(idx)), schema_uri, join_ptr(schema_ptr, "unevaluatedItems"), False, cur_base_uri)
                            if not res.valid:
                                badidx.append(idx)
                    if badidx:
                        names = [str(i + 1) for i in badidx]
                        if len(names) == 1:
                            msg = f"Unevaluated items are not allowed ('{names[0]}' was unexpected)"
                        else:
                            msg = f"Unevaluated items are not allowed ({', '.join(repr(n) for n in names)} were unexpected)"
                        add_err("unevaluatedItems", msg)

        # allOf / anyOf / oneOf / not.
        if isinstance(schema.get("allOf"), list):
            for idx, sub in enumerate(schema["allOf"]):
                if is_schema_obj(sub):
                    res = self.validate(sub, instance, join_ptr(join_ptr(eval_path, "allOf"), str(idx)), inst_path, schema_uri, join_ptr(join_ptr(schema_ptr, "allOf"), str(idx)), collect, cur_base_uri)
                    add_child(res)

        if isinstance(schema.get("anyOf"), list):
            ok = False
            for sub in schema["anyOf"]:
                if is_schema_obj(sub) and self.validate(sub, instance, eval_path, inst_path, schema_uri, schema_ptr, False, cur_base_uri).valid:
                    ok = True; break
            if not ok:
                add_err("anyOf", f"{render_json_value(instance)} is not valid under any of the schemas listed in the 'anyOf' keyword")

        if isinstance(schema.get("oneOf"), list):
            count = 0
            for sub in schema["oneOf"]:
                if is_schema_obj(sub) and self.validate(sub, instance, eval_path, inst_path, schema_uri, schema_ptr, False, cur_base_uri).valid:
                    count += 1
            if count == 0:
                add_err("oneOf", f"{render_json_value(instance)} is not valid under any of the schemas listed in the 'oneOf' keyword")
            elif count > 1:
                add_err("oneOf", f"{render_json_value(instance)} is valid under more than one of the schemas listed in the 'oneOf' keyword")

        if "not" in schema and is_schema_obj(schema["not"]):
            res = self.validate(schema["not"], instance, eval_path, inst_path, schema_uri, schema_ptr, False, cur_base_uri)
            if res.valid:
                add_err("not", f"{render_json_value(schema['not'])} is not allowed for {render_json_value(instance)}")

        if draft_num(self.draft) >= 7 and "if" in schema and is_schema_obj(schema["if"]):
            cond = self.validate(schema["if"], instance, eval_path, inst_path, schema_uri, join_ptr(schema_ptr, "if"), False, cur_base_uri).valid
            if cond and "then" in schema and is_schema_obj(schema["then"]):
                res = self.validate(schema["then"], instance, join_ptr(eval_path, "then"), inst_path, schema_uri, join_ptr(schema_ptr, "then"), collect, cur_base_uri)
                add_child(res)
            if (not cond) and "else" in schema and is_schema_obj(schema["else"]):
                res = self.validate(schema["else"], instance, join_ptr(eval_path, "else"), inst_path, schema_uri, join_ptr(schema_ptr, "else"), collect, cur_base_uri)
                add_child(res)

        valid = len(errors) == 0
        if collect:
            node.valid = valid  # type: ignore
        return ValidationResult(valid, errors, node, eval_props, eval_items)


def unexpected_props_msg(prefix: str, names: List[str]) -> str:
    names = sorted(names)
    if len(names) == 1:
        return f"{prefix} ('{names[0]}' was unexpected)"
    quoted = ", ".join(f"'{n}'" for n in names)
    return f"{prefix} ({quoted} were unexpected)"


def json_report(obj: Dict[str, Any]) -> str:
    return json.dumps(obj, ensure_ascii=False, separators=(",", ":"))


def structured_payload(res: ValidationResult, output: str) -> Dict[str, Any]:
    if output == "flag":
        return {"valid": res.valid}
    if output == "list":
        details = []
        if res.node is not None:
            details = [n.to_obj(False) for n in res.node.flatten()]
        return {"details": details, "valid": res.valid}
    if output == "hierarchical":
        if res.node is not None:
            return res.node.to_obj(True)
        return {"valid": res.valid}
    return {"valid": res.valid}


def print_validation(schema_arg: str, instance_arg: Optional[str], res: ValidationResult, output: str, errors_only: bool) -> None:
    if errors_only and res.valid:
        return
    if output == "text":
        assert instance_arg is not None
        if res.valid:
            print(f"{instance_arg} - VALID")
        else:
            print(f"{instance_arg} - INVALID. Errors:")
            for i, e in enumerate(res.errors, 1):
                print(f"{i}. {e}")
        return
    report: Dict[str, Any] = {}
    if instance_arg is not None:
        report["instance"] = instance_arg
    report["output"] = output
    report["payload"] = structured_payload(res, output)
    report["schema"] = schema_arg
    print(json_report(report))


def print_schema_result(schema_arg: str, valid: bool, err: Optional[str], output: str, errors_only: bool, schema: Any, loader: SchemaLoader, draft: str, opts: Options) -> None:
    if errors_only and valid:
        return
    if output == "text":
        if valid:
            print("Schema is valid")
        else:
            print(f"Schema is invalid. Error: {err}")
        return
    if output == "flag":
        print(json_report({"output": "flag", "payload": {"valid": valid}, "schema": schema_arg}))
        return
    # For list/hierarchical schema-only modes, validate the schema as an instance of a simplified meta-schema.
    # The original emits very detailed meta-schema output; this compact form preserves the public shape.
    root = Node("", "", "https://json-schema.org/draft/2020-12/schema#", valid)
    if not valid and err:
        root.errors = {"schema": err}
    res = ValidationResult(valid, [] if valid else [err or ""], root)
    print(json_report({"output": output, "payload": structured_payload(res, output), "schema": schema_arg}))


def parse_seconds(s: str, optname: str) -> float:
    try:
        val = float(s)
    except Exception:
        cli_error(f"invalid value '{s}' for '{optname} <SECONDS>': '{s}' is not a valid number")
    if not math.isfinite(val) or val < 0:
        cli_error(f"invalid value '{s}' for '{optname} <SECONDS>': must be a non-negative finite number")
    return val


def cli_error(msg: str, usage: Optional[str] = None, tip_value: Optional[str] = None) -> None:
    print(f"error: {msg}", file=sys.stderr)
    print(file=sys.stderr)
    if tip_value is not None:
        print(f"  tip: to pass '{tip_value}' as a value, use '-- {tip_value}'", file=sys.stderr)
        print(file=sys.stderr)
    if usage:
        print(f"Usage: {usage}", file=sys.stderr)
        print(file=sys.stderr)
    print("For more information, try '--help'.", file=sys.stderr)
    raise CliExit(2)


def need_value(args: List[str], i: int, opt: str, display: str) -> Tuple[str, int]:
    if i + 1 >= len(args):
        cli_error(f"a value is required for '{display}' but none was supplied")
    return args[i + 1], i + 1


def parse_args(argv: List[str]) -> Options:
    opts = Options()
    positionals: List[str] = []
    i = 0
    after_dashdash = False
    while i < len(argv):
        a = argv[i]
        if not after_dashdash and a in ("-h", "--help"):
            print(HELP)
            raise CliExit(0)
        if not after_dashdash and a == "--":
            after_dashdash = True
            i += 1
            continue
        if not after_dashdash and a in ("-v", "--version"):
            opts.version = True
            i += 1
            continue
        if not after_dashdash and a in ("-k", "--insecure"):
            opts.insecure = True
            i += 1
            continue
        if not after_dashdash and a == "--assert-format":
            opts.assert_format = True
            i += 1
            continue
        if not after_dashdash and a == "--no-assert-format":
            opts.assert_format = False
            i += 1
            continue
        if not after_dashdash and a == "--errors-only":
            opts.errors_only = True
            i += 1
            continue

        # Long options with possible =.
        if not after_dashdash and a.startswith("--"):
            name, eq, val = a.partition("=")
            def getval(display: str) -> str:
                nonlocal i
                if eq:
                    return val
                v, ni = need_value(argv, i, name, display)
                i = ni
                return v
            if name in ("--instance",):
                v = getval("--instance <INSTANCES>")
                opts.instances.append(v)
                i += 1
                continue
            if name == "--draft":
                v = getval("--draft <DRAFT>")
                if v not in VALID_DRAFTS:
                    cli_error(f"invalid value '{v}' for '--draft <DRAFT>'\n  [possible values: 4, 6, 7, 2019, 2020]")
                opts.draft = v
                i += 1
                continue
            if name == "--output":
                v = getval("--output <OUTPUT>")
                if v not in OUTPUTS:
                    cli_error(f"invalid value '{v}' for '--output <OUTPUT>'\n  [possible values: text, flag, list, hierarchical]")
                opts.output = v
                i += 1
                continue
            if name == "--connect-timeout":
                v = getval("--connect-timeout <SECONDS>")
                opts.connect_timeout = parse_seconds(v, "--connect-timeout")
                i += 1
                continue
            if name == "--timeout":
                v = getval("--timeout <SECONDS>")
                opts.timeout = parse_seconds(v, "--timeout")
                i += 1
                continue
            if name == "--cacert":
                v = getval("--cacert <FILE>")
                opts.cacert = v
                i += 1
                continue
            tip = a if a.startswith("-") else None
            usage = "executable [OPTIONS] [SCHEMA]" if not positionals else "executable <SCHEMA>"
            if opts.version:
                usage = "executable --version [SCHEMA]"
            cli_error(f"unexpected argument '{a}' found", usage=usage, tip_value=tip)

        if not after_dashdash and a.startswith("-") and a != "-":
            # Short value options can be attached, e.g. -d7, -ifile.
            if a.startswith("-i") and len(a) > 2:
                opts.instances.append(a[2:])
                i += 1
                continue
            if a == "-i":
                v, ni = need_value(argv, i, "-i", "--instance <INSTANCES>")
                opts.instances.append(v)
                i = ni + 1
                continue
            if a.startswith("-d") and len(a) > 2:
                v = a[2:]
                if v not in VALID_DRAFTS:
                    cli_error(f"invalid value '{v}' for '--draft <DRAFT>'\n  [possible values: 4, 6, 7, 2019, 2020]")
                opts.draft = v
                i += 1
                continue
            if a == "-d":
                v, ni = need_value(argv, i, "-d", "--draft <DRAFT>")
                if v not in VALID_DRAFTS:
                    cli_error(f"invalid value '{v}' for '--draft <DRAFT>'\n  [possible values: 4, 6, 7, 2019, 2020]")
                opts.draft = v
                i = ni + 1
                continue
            tip = a
            usage = "executable [OPTIONS] [SCHEMA]"
            cli_error(f"unexpected argument '{a}' found", usage=usage, tip_value=tip)

        # Positional schema.
        positionals.append(a)
        if len(positionals) > 1:
            cli_error(f"unexpected argument '{a}' found", usage="executable [OPTIONS] [SCHEMA]")
        i += 1

    if opts.version:
        print(f"Version: {VERSION}")
        raise CliExit(0)

    if positionals:
        opts.schema = positionals[0]
    else:
        # Usage line changes when options were present in observed Clap output.
        if opts.instances:
            usage = "executable --instance <INSTANCES> <SCHEMA>"
        else:
            usage = "executable <SCHEMA>"
        print("error: the following required arguments were not provided:", file=sys.stderr)
        print("  <SCHEMA>", file=sys.stderr)
        print(file=sys.stderr)
        print(f"Usage: {usage}", file=sys.stderr)
        print(file=sys.stderr)
        print("For more information, try '--help'.", file=sys.stderr)
        raise CliExit(2)
    return opts


def run(argv: List[str]) -> int:
    try:
        opts = parse_args(argv)
        assert opts.schema is not None
        schema = parse_json_file(opts.schema)
        loader = SchemaLoader(schema, opts.schema, opts)

        if opts.instances:
            effective_draft = opts.draft or detect_draft(schema, "2020")
        else:
            # Observed schema-only mode ignores --draft and uses $schema/default.
            effective_draft = detect_draft(schema, "2020")

        try:
            validate_schema_meta(schema, effective_draft, loader, loader.root_uri)
            schema_valid = True
            schema_err = None
        except SchemaInvalid as e:
            schema_valid = False
            schema_err = e.message
        except RuntimeCliError as e:
            print(f"Error: {e}")
            return 1

        if not opts.instances:
            print_schema_result(opts.schema, schema_valid, schema_err, opts.output, opts.errors_only, schema, loader, effective_draft, opts)
            return 0 if schema_valid else 1

        if not schema_valid:
            if opts.output == "text":
                print(f"Schema is invalid. Error: {schema_err}")
            else:
                # Match flag shape; list/hierarchical compactly report invalid schema.
                print_schema_result(opts.schema, False, schema_err, opts.output, opts.errors_only, schema, loader, effective_draft, opts)
            return 1

        validator = Validator(loader, effective_draft, opts.assert_format)
        any_invalid = False
        collect = opts.output in ("list", "hierarchical")
        for inst_path in opts.instances:
            inst = parse_json_file(inst_path)
            res = validator.validate(schema, inst, collect=collect)
            if not res.valid:
                any_invalid = True
            print_validation(opts.schema, inst_path, res, opts.output, opts.errors_only)
        return 1 if any_invalid else 0
    except CliExit as e:
        return e.code
    except RuntimeCliError as e:
        print(f"Error: {e}")
        return 1
    except SchemaInvalid as e:
        print(f"Schema is invalid. Error: {e.message}")
        return 1
    except BrokenPipeError:
        return 1


if __name__ == "__main__":
    sys.exit(run(sys.argv[1:]))
